std::vector<int> source = {10, 20, 30};
std::vector<int> dest;

// Standard library algorithms operate on half-open ranges [first, last)
auto first = source.begin();
auto last = source.end();

// Use std::back_inserter for dynamic resizing
std::copy(first, last,
          std::back_inserter(dest));

// dest now contains {10, 20, 30}
// Range access via C++20 helper:
auto size = std::distance(first, last); // size == 3
auto r_size = std::ranges::size(source); // C++20 concept
// r_size == 3
std::vector<int> doubled(3);

// Using std::transform
std::transform(source.begin(), source.end(),
               doubled.begin(),
               [](int x){ return x * 2; });
// doubled == {20, 40, 60}
